  3	import com.loja.pedidos.client.TransLogClient;
  4	import com.loja.pedidos.dto.*;
  5	import com.loja.pedidos.entity.Produto;
  6	import com.loja.pedidos.exception.ErroNegocio;
  7	import com.loja.pedidos.repository.PedidoRepository;
  8	import com.loja.pedidos.repository.ProdutoRepository;
  9	import com.loja.pedidos.util.ArredondamentoUtil;
 10	import lombok.RequiredArgsConstructor;
 11	import org.springframework.stereotype.Service;
 12	
 13	import java.math.BigDecimal;
 14	import java.math.RoundingMode;
 15	import java.time.Instant;
 16	import java.time.temporal.ChronoUnit;
