 19	@Service
 20	@RequiredArgsConstructor
 21	public class CalculoService {
 22	    private final ProdutoRepository produtoRepository;
 23	    private final PedidoRepository pedidoRepository;
 24	    private final TransLogClient transLogClient;
 25	
 26	    public Resumo calcularResumo(DadosCompra dados) {
 27	        validarDados(dados);
 28	
 29	        var subtotal = calcularSubtotal(dados);
 30	        var descontoCupom = calcularDescontoCupom(dados, subtotal);
 31	        var frete = calcularFrete(dados);
 32	        var prazoEntrega = calcularPrazoEntrega(dados);
 33	        var seguro = calcularSeguro(dados, subtotal);
 34	        var totalAntesAjuste = subtotal.subtract(descontoCupom).add(frete).add(seguro);
 35	        var ajuste = calcularAjustePagamento(dados, totalAntesAjuste);
 36	        var totalFinal = totalAntesAjuste.add(ajuste);
 37	        var credito = calcularCreditoClube(dados, subtotal);
 38	        var brinde = verificarBrinde(dados, subtotal);
 39	
 40	        var parcelas = dados.getParcelas() != null ? dados.getParcelas() : 1;
 41	        var valorParcela = calcularValorParcela(totalFinal, parcelas, dados.getFormaPagamento());
 42	
 43	        return Resumo.builder()
 44	            .subtotalProdutos(ArredondamentoUtil.arredondar(subtotal))
 45	            .descontoCupom(ArredondamentoUtil.arredondar(descontoCupom))
 46	            .frete(ArredondamentoUtil.arredondar(frete))
 47	            .prazoEntregaDias(prazoEntrega)
 48	            .seguro(ArredondamentoUtil.arredondar(seguro))
 49	            .ajustePagamento(ArredondamentoUtil.arredondar(ajuste))
 50	            .totalFinal(ArredondamentoUtil.arredondar(totalFinal))
 51	            .parcelas(parcelas)
 52	            .valorParcela(ArredondamentoUtil.arredondar(valorParcela))
 53	            .creditoProximaCompra(ArredondamentoUtil.arredondar(credito))
 54	            .brinde(brinde)
 55	            .build();
 56	    }
 57	
 58	    private void validarDados(DadosCompra dados) {
 59	        if (dados.getItens() == null || dados.getItens().isEmpty()) {
 60	            throw ErroNegocio.pedidoInvalido("Carrinho vazio");
 61	        }
 62	
 63	        if (dados.getCliente() == null || dados.getCliente().getCpf() == null || dados.getCliente().getEmail() == null) {
 64	            throw ErroNegocio.pedidoInvalido("CPF ou e-mail ausente");
 65	        }
 66	
 67	        Set<String> skusVistos = new HashSet<>();
 68	        for (var item : dados.getItens()) {
 69	            if (item.getSku() == null || item.getSku().trim().isEmpty()) {
 70	                throw ErroNegocio.pedidoInvalido("Item sem SKU");
 71	            }
 72	            if (skusVistos.contains(item.getSku())) {
 73	                throw ErroNegocio.pedidoInvalido("O mesmo SKU duas vezes no carrinho");
 74	            }
 75	            skusVistos.add(item.getSku());
 76	
 77	            if (item.getQuantidade() == null || item.getQuantidade() <= 0) {
 78	                throw ErroNegocio.pedidoInvalido("Quantidade zero, negativa ou ausente");
 79	            }
 80	        }
 81	
 82	        if (dados.getNivelClube() == null) {
 83	            throw ErroNegocio.nivelClubeInvalido();
 84	        }
 85	
 86	        try {
 87	            DadosCompra.NivelClube.valueOf(dados.getNivelClube().name());
 88	        } catch (IllegalArgumentException e) {
 89	            throw ErroNegocio.nivelClubeInvalido();
 90	        }
 91	
 92	        if (dados.getRegiao() == null) {
 93	            throw ErroNegocio.regiaoInvalida();
 94	        }
 95	
 96	        if (dados.getCep() == null || !dados.getCep().matches("\\d{8}")) {
 97	            throw ErroNegocio.cepInvalido();
 98	        }
 99	
100	        if (dados.getModalidadeEntrega() == null) {
101	            throw ErroNegocio.modalidadeInvalida();
102	        }
103	
104	        if (dados.getFormaPagamento() == null) {
105	            throw ErroNegocio.formaPagamentoInvalida();
106	        }
107	
108	        var parcelas = dados.getParcelas() != null ? dados.getParcelas() : 1;
109	        validarParcelamento(dados.getFormaPagamento(), parcelas);
110	
111	        validarProdutos(dados);
112	        validarCupom(dados);
113	        validarModalidade(dados);
114	        validarFormaPagamento(dados);
115	    }
116	
117	    private void validarProdutos(DadosCompra dados) {
118	        for (var item : dados.getItens()) {
119	            var produto = produtoRepository.findById(item.getSku());
120	            if (produto.isEmpty()) {
121	                throw ErroNegocio.produtoInexistente(item.getSku());
122	            }
123	
124	            var p = produto.get();
125	            if (p.isForaDeLinha()) {
126	                throw ErroNegocio.produtoForaDeLinha(item.getSku());
127	            }
128	
129	            if (p.getEstoque() < item.getQuantidade()) {
130	                throw ErroNegocio.estoqueInsuficiente(item.getSku());
131	            }
132	        }
133	    }
134	
135	    private void validarCupom(DadosCompra dados) {
136	        if (dados.getCupom() == null || dados.getCupom().trim().isEmpty()) {
137	            return;
138	        }
139	
140	        var cupom = dados.getCupom().trim().toUpperCase();
141	
142	        switch (cupom) {
143	            case "BEMVINDO10":
144	                validarBemVindo10(dados);
145	                break;
146	            case "MENOS50":
147	                validarMenos50(dados);
148	                break;
149	            case "FRETEGRATIS":
150	                break;
151	            case "LEVE3PAGUE2":
152	                break;
153	            default:
154	                throw ErroNegocio.cupomInvalido();
155	        }
156	    }
157	
158	    private void validarBemVindo10(DadosCompra dados) {
159	        var cpf = dados.getCliente().getCpf();
160	        var pedidosAntigos = pedidoRepository.findByCpfCliente(cpf)
161	            .stream()
162	            .filter(p -> {
163	                var sit = p.getSituacao();
164	                return sit == com.loja.pedidos.entity.Pedido.SituacaoPedido.PAGO ||
165	                       sit == com.loja.pedidos.entity.Pedido.SituacaoPedido.ENVIADO ||
166	                       sit == com.loja.pedidos.entity.Pedido.SituacaoPedido.ENTREGUE;
167	            })
168	            .count();
169	
170	        if (pedidosAntigos > 0) {
171	            throw ErroNegocio.cupomNaoAplicavel();
172	        }
173	    }
174	
175	    private void validarMenos50(DadosCompra dados) {
176	        var subtotal = calcularSubtotal(dados);
177	        if (subtotal.compareTo(new BigDecimal("300.00")) < 0) {
178	            throw ErroNegocio.cupomNaoAplicavel();
179	        }
180	    }
181	
182	    private void validarModalidade(DadosCompra dados) {
183	        try {
184	            DadosCompra.ModalidadeEntrega.valueOf(dados.getModalidadeEntrega().name());
185	        } catch (IllegalArgumentException e) {
186	            throw ErroNegocio.modalidadeInvalida();
187	        }
188	
189	        var peso = calcularPeso(dados);
190	        if (dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.MOTOBOY && peso.compareTo(new BigDecimal("5.00")) > 0) {
191	            throw ErroNegocio.modalidadeIndisponivel();
192	        }
193	
194	        if (dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.ECONOMICA ||
195	            dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.EXPRESSA) {
196	            var cotacao = transLogClient.cotacao(dados.getCep(), peso, dados.getModalidadeEntrega().name());
197	            if (cotacao == null) {
198	                throw ErroNegocio.modalidadeIndisponivel();
199	            }
200	        }
201	    }
202	
203	    private void validarFormaPagamento(DadosCompra dados) {
204	        var subtotal = calcularSubtotal(dados);
205	        var descontoCupom = calcularDescontoCupom(dados, subtotal);
206	        var frete = calcularFrete(dados);
207	        var seguro = calcularSeguro(dados, subtotal);
208	        var totalAntesAjuste = subtotal.subtract(descontoCupom).add(frete).add(seguro);
209	
210	        if (dados.getFormaPagamento() == DadosCompra.FormaPagamento.BOLETO &&
211	            totalAntesAjuste.compareTo(new BigDecimal("1000.00")) > 0) {
212	            throw ErroNegocio.formaPagamentoIndisponivel();
213	        }
214	    }
215	
216	    private void validarParcelamento(DadosCompra.FormaPagamento forma, int parcelas) {
217	        if (forma == DadosCompra.FormaPagamento.PIX || forma == DadosCompra.FormaPagamento.BOLETO) {
218	            if (parcelas != 1) {
219	                throw ErroNegocio.parcelamentoInvalido();
220	            }
221	        }
222	
223	        if (forma == DadosCompra.FormaPagamento.CARTAO) {
224	            if (parcelas < 1 || parcelas > 12) {
225	                throw ErroNegocio.parcelamentoInvalido();
226	            }
227	        }
228	    }
229	
230	    private BigDecimal calcularSubtotal(DadosCompra dados) {
231	        BigDecimal subtotal = BigDecimal.ZERO;
232	        for (var item : dados.getItens()) {
233	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
234	            var valor = produto.getPreco().multiply(new BigDecimal(item.getQuantidade()));
235	            subtotal = subtotal.add(valor);
236	        }
237	        return ArredondamentoUtil.arredondar(subtotal);
238	    }
239	
240	    private BigDecimal calcularDescontoCupom(DadosCompra dados, BigDecimal subtotal) {
241	        if (dados.getCupom() == null || dados.getCupom().trim().isEmpty()) {
242	            return BigDecimal.ZERO;
243	        }
244	
245	        var cupom = dados.getCupom().trim().toUpperCase();
246	
247	        switch (cupom) {
248	            case "BEMVINDO10":
249	                return ArredondamentoUtil.arredondar(subtotal.multiply(new BigDecimal("0.10")));
250	            case "MENOS50":
251	                return ArredondamentoUtil.arredondar(new BigDecimal("50.00"));
252	            case "FRETEGRATIS":
253	                return ArredondamentoUtil.arredondar(calcularFrete(dados));
254	            case "LEVE3PAGUE2":
255	                return calcularDescontoLeve3Pague2(dados, subtotal);
256	            default:
257	                return BigDecimal.ZERO;
258	        }
259	    }
260	
261	    private BigDecimal calcularDescontoLeve3Pague2(DadosCompra dados, BigDecimal subtotal) {
262	        BigDecimal desconto = BigDecimal.ZERO;
263	        for (var item : dados.getItens()) {
264	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
265	            var unidadesGratis = item.getQuantidade() / 3;
266	            var precoGratis = produto.getPreco().multiply(new BigDecimal(unidadesGratis));
267	            desconto = desconto.add(precoGratis);
268	        }
269	        return ArredondamentoUtil.arredondar(desconto);
270	    }
271	
272	    private BigDecimal calcularFrete(DadosCompra dados) {
273	        switch (dados.getModalidadeEntrega()) {
274	            case RETIRADA_LOJA:
275	                return BigDecimal.ZERO;
276	            case MOTOBOY:
277	                return ArredondamentoUtil.arredondar(new BigDecimal("18.00"));
278	            case ECONOMICA:
279	            case EXPRESSA:
280	                var peso = calcularPeso(dados);
281	                var cotacao = transLogClient.cotacao(dados.getCep(), peso, dados.getModalidadeEntrega().name());
282	                if (cotacao != null) {
283	                    return ArredondamentoUtil.arredondar(cotacao.getValor());
284	                }
285	                return BigDecimal.ZERO;
286	            default:
287	                return BigDecimal.ZERO;
288	        }
289	    }
290	
291	    private Integer calcularPrazoEntrega(DadosCompra dados) {
292	        var prazoBase = 0;
293	
294	        switch (dados.getModalidadeEntrega()) {
295	            case RETIRADA_LOJA:
296	                prazoBase = 1;
297	                break;
298	            case MOTOBOY:
299	                prazoBase = 0;
300	                break;
301	            case ECONOMICA:
302	            case EXPRESSA:
303	                var peso = calcularPeso(dados);
304	                var cotacao = transLogClient.cotacao(dados.getCep(), peso, dados.getModalidadeEntrega().name());
305	                if (cotacao != null) {
306	                    prazoBase = cotacao.getPrazoDias();
307	                }
308	                break;
309	        }
310	
311	        if ((dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.ECONOMICA ||
312	             dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.EXPRESSA)) {
313	            switch (dados.getRegiao()) {
314	                case NORTE:
315	                    prazoBase += 3;
316	                    break;
317	                case NORDESTE:
318	                    prazoBase += 2;
319	                    break;
320	            }
321	        }
322	
323	        return prazoBase;
324	    }
325	
326	    private BigDecimal calcularSeguro(DadosCompra dados, BigDecimal subtotal) {
327	        var percentual = getPercentualSeguro(dados.getRegiao());
328	        var seguro = subtotal.multiply(percentual).divide(new BigDecimal("100"));
329	        seguro = ArredondamentoUtil.arredondar(seguro);
330	
331	        var limite = getLimiteSeguro(dados.getRegiao());
332	        if (limite != null && seguro.compareTo(limite) > 0) {
333	            return limite;
334	        }
335	
336	        return seguro;
337	    }
338	
339	    private BigDecimal getPercentualSeguro(DadosCompra.Regiao regiao) {
340	        return switch (regiao) {
341	            case SUDESTE, SUL -> new BigDecimal("1.00");
342	            case CENTRO_OESTE -> new BigDecimal("1.50");
343	            case NORTE -> new BigDecimal("2.50");
344	            case NORDESTE -> new BigDecimal("2.00");
345	        };
346	    }
347	
348	    private BigDecimal getLimiteSeguro(DadosCompra.Regiao regiao) {
349	        return switch (regiao) {
350	            case NORTE, NORDESTE -> new BigDecimal("30.00");
351	            default -> null;
352	        };
353	    }
354	
355	    private BigDecimal calcularAjustePagamento(DadosCompra dados, BigDecimal total) {
356	        var forma = dados.getFormaPagamento();
357	        var parcelas = dados.getParcelas() != null ? dados.getParcelas() : 1;
358	
359	        if (forma == DadosCompra.FormaPagamento.PIX && (dados.getCupom() == null || dados.getCupom().trim().isEmpty())) {
360	            var desconto = total.multiply(new BigDecimal("0.05"));
361	            return ArredondamentoUtil.arredondar(desconto.negate());
362	        }
363	
364	        if (forma == DadosCompra.FormaPagamento.BOLETO) {
365	            return ArredondamentoUtil.arredondar(new BigDecimal("3.49"));
366	        }
367	
368	        if (forma == DadosCompra.FormaPagamento.CARTAO && parcelas > 3) {
369	            var taxa = new BigDecimal("0.0199");
370	            var expoente = parcelas;
371	            var denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.add(taxa).pow(-expoente));
372	            var jurosTotal = total.multiply(taxa).divide(denominador, 10, RoundingMode.HALF_EVEN);
373	            jurosTotal = ArredondamentoUtil.arredondar(jurosTotal);
374	            return jurosTotal;
375	        }
376	
377	        return BigDecimal.ZERO;
378	    }
379	
380	    private BigDecimal calcularValorParcela(BigDecimal total, int parcelas, DadosCompra.FormaPagamento forma) {
381	        if (forma == DadosCompra.FormaPagamento.CARTAO && parcelas > 3) {
382	            var taxa = new BigDecimal("0.0199");
383	            var expoente = parcelas;
384	            var denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.add(taxa).pow(-expoente));
385	            var parcela = total.multiply(taxa).divide(denominador, 10, RoundingMode.HALF_EVEN);
386	            return ArredondamentoUtil.arredondar(parcela);
387	        }
388	
389	        var parcela = total.divide(new BigDecimal(parcelas), 10, RoundingMode.HALF_EVEN);
390	        return ArredondamentoUtil.arredondar(parcela);
391	    }
392	
393	    private BigDecimal calcularCreditoClube(DadosCompra dados, BigDecimal subtotal) {
394	        var nivel = dados.getNivelClube();
395	
396	        switch (nivel) {
397	            case PRATA:
398	                var creditoPrata = subtotal.multiply(new BigDecimal("0.02"));
399	                return ArredondamentoUtil.arredondar(creditoPrata);
400	            case OURO:
401	                var creditoOuro = subtotal.multiply(new BigDecimal("0.05"));
402	                return ArredondamentoUtil.arredondar(creditoOuro);
403	            default:
404	                return BigDecimal.ZERO;
405	        }
406	    }
407	
408	    private boolean verificarBrinde(DadosCompra dados, BigDecimal subtotal) {
409	        if (dados.getNivelClube() != DadosCompra.NivelClube.OURO) {
410	            return false;
411	        }
412	
413	        if (dados.getModalidadeEntrega() == DadosCompra.ModalidadeEntrega.MOTOBOY) {
414	            return false;
415	        }
416	
417	        return subtotal.compareTo(new BigDecimal("500.00")) > 0;
418	    }
419	
420	    private BigDecimal calcularPeso(DadosCompra dados) {
421	        BigDecimal peso = BigDecimal.ZERO;
422	        for (var item : dados.getItens()) {
423	            var produto = produtoRepository.findById(item.getSku()).orElseThrow();
424	            var pesoItem = produto.getPesoKg().multiply(new BigDecimal(item.getQuantidade()));
425	            peso = peso.add(pesoItem);
426	        }
427	        return peso;
428	    }
429	}
