442	import org.springframework.web.client.ResourceAccessException;
443	
444	import java.math.BigDecimal;
445	
446	@Service
447	@RequiredArgsConstructor
448	@Slf4j
449	public class TransLogClient {
450	    private final TransLogConfig config;
451	    private final RestTemplate restTemplate;
452	
453	    public TransLogCotacao cotacao(String cep, BigDecimal pesoKg, String servico) {
454	        try {
455	            String url = config.getUrl() + "/cotacao?cep=" + cep + "&pesoKg=" + pesoKg + "&servico=" + servico;
456	
457	            log.debug("Chamando TransLog: {}", url);
458	            var response = restTemplate.getForObject(url, TransLogCotacao.class);
459	            return response;
460	        } catch (HttpClientErrorException.NotFound e) {
461	            log.debug("CEP não atendido pela TransLog");
462	            return null;
463	        } catch (ResourceAccessException e) {
464	            log.warn("Timeout ao chamar TransLog");
465	            throw ErroNegocio.transportadoraIndisponivel();
466	        } catch (Exception e) {
467	            log.error("Erro ao chamar TransLog", e);
468	            throw ErroNegocio.transportadoraIndisponivel();
469	        }
470	    }
471	
472	    @Data
473	    @NoArgsConstructor
474	    @AllArgsConstructor
475	    public static class TransLogCotacao {
476	        private BigDecimal valor;
477	        private Integer prazoDias;
478	    }
479	}

