113	    @Transactional
114	    public RespostaPedido registrarEnvio(Long id, RequisicaoEnvio requisicao) {
115	        var pedido = pedidoRepository.findById(id)
116	            .orElseThrow(ErroNegocio::pedidoNaoEncontrado);
117	
118	        if (pedido.getSituacao() != Pedido.SituacaoPedido.PAGO) {
119	            throw ErroNegocio.operacaoNaoPermitida();
120	        }
121	
