   334	
   335	@Service
   336	@RequiredArgsConstructor
   337	public class AvisoService {
   338	    private final AvisoRepository avisoRepository;
   339	
   340	    public List<RespostaAviso> obterAvisos(String cpf) {
   341	        return avisoRepository.findByCpfClienteOrderByIdAsc(cpf)
   342	            .stream()
   343	            .map(this::mapearAviso)
   344	            .collect(Collectors.toList());
   345	    }
   346	
   347	    @Transactional
   348	    public RespostaAviso marcarComoLido(Long id) {
   349	        var aviso = avisoRepository.findById(id)
   350	            .orElseThrow(ErroNegocio::avisoNaoEncontrado);
   351	
   352	        aviso.setSituacao(Aviso.SituacaoAviso.LIDO);
   353	        avisoRepository.save(aviso);
   354	
   355	        return mapearAviso(aviso);
   356	    }
   357	
   358	    private RespostaAviso mapearAviso(Aviso aviso) {
   359	        return RespostaAviso.builder()
   360	            .id(aviso.getId())
   361	            .tipo(aviso.getTipo().name())
   362	            .pedidoId(aviso.getPedidoId())
   363	            .situacao(aviso.getSituacao().name())
   364	            .build();
   365	    }
   366	}
