   359	        return RespostaAviso.builder()
   360	            .id(aviso.getId())
   361	            .tipo(aviso.getTipo().name())
   362	            .pedidoId(aviso.getPedidoId())
   363	            .situacao(aviso.getSituacao().name())
   364	            .build();
